// Mechanism of std::reverse_iterator<Iter>
template <typename Iter>
class reverse_iterator {
private:
    Iter current; // Base iterator, points one past the logical element
public:
    // Core definition: Dereference returns the value *before* 'current'
    decltype(auto) operator*() const {
        Iter tmp = current;
        return *(--tmp); 
    }

    // Reverse iterator increment (++) maps to base iterator decrement (--)
    reverse_iterator& operator++() {
        --current; 
        return *this;
    }

    Iter base() const { return current; }
};

// Usage Example
std::vector<int> v = {1, 2, 3};
auto rit = std::make_reverse_iterator(v.end()); // Base is v.end()
// *rit == 3 (Dereferences v.end() - 1)
// ++rit moves base to v.end() - 1
